import{_ as a,H as s,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"加餐 | 集中答疑：详解Android环境搭建","description":"","frontmatter":{},"headers":[{"level":2,"title":"Homebrew","slug":"homebrew","link":"#homebrew","children":[]},{"level":2,"title":"Node 和 NPM","slug":"node-和-npm","link":"#node-和-npm","children":[]},{"level":2,"title":"Watchman","slug":"watchman","link":"#watchman","children":[]},{"level":2,"title":"安装 JDK","slug":"安装-jdk","link":"#安装-jdk","children":[]},{"level":2,"title":"安装 Android Studio","slug":"安装-android-studio","link":"#安装-android-studio","children":[]},{"level":2,"title":"安装 Android SDK","slug":"安装-android-sdk","link":"#安装-android-sdk","children":[]},{"level":2,"title":"配置 Android 环境变量","slug":"配置-android-环境变量","link":"#配置-android-环境变量","children":[]},{"level":2,"title":"安装 Android 模拟器","slug":"安装-android-模拟器","link":"#安装-android-模拟器","children":[]},{"level":2,"title":"创建 React Native 项目","slug":"创建-react-native-项目","link":"#创建-react-native-项目","children":[]},{"level":2,"title":"启动 React Native 项目","slug":"启动-react-native-项目","link":"#启动-react-native-项目","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ReactNative新架构实战课/加餐｜集中答疑：详解Android环境搭建.md","filePath":"ReactNative新架构实战课/加餐｜集中答疑：详解Android环境搭建.md","lastUpdated":1795533704000}'),n={name:"ReactNative新架构实战课/加餐｜集中答疑：详解Android环境搭建.md"};function E(p,e,A,o,l,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="加餐-集中答疑-详解android环境搭建" tabindex="-1">加餐 | 集中答疑：详解Android环境搭建 <a class="header-anchor" href="#加餐-集中答疑-详解android环境搭建" aria-label="Permalink to &quot;加餐 | 集中答疑：详解Android环境搭建&quot;">​</a></h1><p>你好，我是蒋宏伟。</p><p>今天这节课，我会为你解答如何搭建 Android 环境。</p><p>在写这节课之前，我自己重装系统重新搭建了一次环境。我使用的电脑是 Macbook Pro 2016版，系统版本是 12.6.3，供你参考。</p><p>总体上说，搭建 Android 环境比搭建 iOS 环境遇到的网络问题更少，因此我更建议新手直接搭建 Android 环境。并在每搭建一步之后做一次检查，比如相关包的版本检查，这可能会让你少走弯路。</p><p>下面我来分享一下，我搭建 Android React Native 开发环境的详细步骤，你也可以跟着一起动起手来。</p><h2 id="homebrew" tabindex="-1">Homebrew <a class="header-anchor" href="#homebrew" aria-label="Permalink to &quot;Homebrew&quot;">​</a></h2><p>第一步是安装 Homebrew，后续很多程序的安装都会借助 Homebrew 进行。</p><p>Homebrew 是 macOS 的一个软件包管理器。直接使用 Homebrew 官方文档进行安装，我</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这边出现了网络报错。报错的内容是 unable to access github，也就是访问不到</span></span></code></pre></div><p>GitHub 地址。解决方案要么是保持自己的网络畅通，要么使用相关的镜像源。</p><p>知乎上有大牛提供了 Homebrew 镜像源及工具，你可以通过如下命令一键安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ /bin/zsh -c &quot;$(curl -fsSL &lt;​https://gitee.com/cunkai/HomebrewCN/raw/master/Homeb</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/1.png" alt=""></a></p><p>安装完成后，重启当前 Terminal，brew 就安装成功了。你可以运行如下命令，检查它是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew --version</span></span>
<span class="line"><span>Homebrew 3.6.15</span></span></code></pre></div><h2 id="node-和-npm" tabindex="-1">Node 和 NPM <a class="header-anchor" href="#node-和-npm" aria-label="Permalink to &quot;Node 和 NPM&quot;">​</a></h2><p>第二步是安装 Node 和 NPM，搭建 JavaScript 环境。</p><p>Node 是 React Native 应用程序中，JavaScript 相关服务的运行环境，比如构建服务就是通过Node 环境提供的。安装 Node 时，会自动安装 NPM 包管理器，它将帮助我们管理相关依赖。</p><p>我们可以通过 Homebrew 进行 Node 的安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install node</span></span></code></pre></div><p>安装完成后，你可以通过如下命令检查 Node 和 NPM 是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ node --version</span></span>
<span class="line"><span>v19.7.0</span></span>
<span class="line"><span>$ npm --version</span></span>
<span class="line"><span>9.5.0</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/2.png" alt=""></a></p><p>为保证后续网络的畅通，你最好将 NPM 的 registry 设置为淘宝源。切换命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ npx nrm use taobao</span></span></code></pre></div><h2 id="watchman" tabindex="-1">Watchman <a class="header-anchor" href="#watchman" aria-label="Permalink to &quot;Watchman&quot;">​</a></h2><p>第三步，是安装一个名为 Watchman 的工具。它是由 Facebook 开发的一个工具，只要你的文件有一些变化，它就会自动重新运行你的项目。</p><p>我们使用 Homebrew 来安装 Watchman。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install watchman</span></span></code></pre></div><p>安装完成后，通过如下命令检查是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ watchman --version</span></span>
<span class="line"><span>2023.02.20.00</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/3.png" alt=""></a></p><h2 id="安装-jdk" tabindex="-1">安装 JDK <a class="header-anchor" href="#安装-jdk" aria-label="Permalink to &quot;安装 JDK&quot;">​</a></h2><p>第四步是安装 Java Development Kit（JDK），搭建 Java 开发环境。</p><p>众所周知，Android 依赖 Java 开发环境，这里我们搭建 Java 环境使用的工具是 Zulu。Zulu是一款 Java 运行环境，它是基于 OpenJDK（一个 Java 编程语言的开源实现的源代码）构建的。Zulu 提供了 Intel 和 M1 Mac 的 JDK，这使得 JDK 的安装更为方便。</p><p>由于 Zulu 是一个图形界面程序，需要手动安装，为了方便这里我们借助 Cask 一键安装。你需要先借助 Homebrew 安装 Cask 再安装 Zulu。命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew tap homebrew/cask-versions</span></span>
<span class="line"><span>$ brew install --cask zulu11</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/4.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当你安装成功后，你可以运行 java --version 检查 Java 运行时环境（JRE）的版本，或</span></span>
<span class="line"><span>运行 javac --version 检查 Java 开发工具包（JDK）中 Java 编译器（javac）的版本。</span></span>
<span class="line"><span>$ java --version</span></span>
<span class="line"><span>java 16.0.2 2021-07-20</span></span>
<span class="line"><span>$ javac --version</span></span>
<span class="line"><span>javac 16.0.2</span></span></code></pre></div><h2 id="安装-android-studio" tabindex="-1">安装 Android Studio <a class="header-anchor" href="#安装-android-studio" aria-label="Permalink to &quot;安装 Android Studio&quot;">​</a></h2><p>第五步是安装 Android Studio，它是搭建 Android 开发环境的前提条件。</p><p>Android Studio 是 Android 开发的官方集成开发环境（IDE）。你需要安装 Android Studio 才能在本机构建 React Native 应用程序，并运行在真机或模拟器上。</p><p>你可以从 Android Studio 官方网站下载和安装 Android Studio。在 Android Studio 安装向导中，选择默认选项并设置相关镜像安装默认依赖即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/5.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯： https://mirrors.cloud.tencent.com/AndroidSDK/</span></span>
<span class="line"><span>阿里： https://mirrors.aliyun.com/android.googlesource.com/</span></span></code></pre></div><p>这一步的完整流程比较长，细节比较多，因此我录了一个小视频，供你参考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/6.jpeg" alt=""></a></p><h2 id="安装-android-sdk" tabindex="-1">安装 Android SDK <a class="header-anchor" href="#安装-android-sdk" aria-label="Permalink to &quot;安装 Android SDK&quot;">​</a></h2><p>第六步是安装 Android SDK。</p><p>在上一步中，我们已经把 Android Studio 和默认依赖安装好了，除了默认依赖，你还需要安装：</p><ul><li>Android SDK Platform 33</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Intel x86 Atom_64 System Image 或 Google APIs Intel x86 Atom System</span></span>
<span class="line"><span>Image(Inter CPU)  或 Google APIs ARM 64 v8a System Image (Apple CPU)</span></span>
<span class="line"><span>Android SDK Build-Tools 33.0.0 版本</span></span>
<span class="line"><span>安装的第一部分的是 Android SDK Platform。它是指针对 Android 特定版本的 Android</span></span></code></pre></div><p>平台组件，包括库、工具和框架等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>安装的第二部分的是 System Image。它是针对特定处理器架构的 Android 系统镜像，该镜</span></span></code></pre></div><p>像主要用于在模拟器上模拟具有特定 CPU 和 Google API 的 Android 设备。带有 Intel 字样的适配的是 Intel CPU，带有 ARM 字样的适配的是苹果 CPU，此外带有 Google 字样表示集成了 Google 的 API。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一般情况下，Intel CPU 选择 Google APIs Intel x86 Atom System Image，苹果</span></span>
<span class="line"><span>CPU 选择 Google APIs ARM 64 v8a System Image。</span></span>
<span class="line"><span>安装的第三部分是 Android SDK Build-Tools，你可以在 Android Studio 的左上角找到</span></span>
<span class="line"><span>Preference，并打开它。然后搜索 Android SDK，找到其中的 SDK Platforms 和 SDK</span></span>
<span class="line"><span>Tools 配置页，然后按下图所示勾选，最后点击 Apply 完成相关项的安装。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/7.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/8.png" alt=""></a></p><p>同样，这一步我也录制了视频。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/9.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/9.jpeg" alt=""></a></p><h2 id="配置-android-环境变量" tabindex="-1">配置 Android 环境变量 <a class="header-anchor" href="#配置-android-环境变量" aria-label="Permalink to &quot;配置 Android 环境变量&quot;">​</a></h2><p>第七步是配置 Android 环境变量。</p><p>由于后续操作会依赖于一些命令行，因此你还需要将 Android 环境变量暴露到全局，以便使用。</p><p>Zsh（Z shell）和 Bash（Bourne Again SHell）是两种不同的命令工具，你可以运行如下命令检查你用的是哪种工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo $SHELL</span></span>
<span class="line"><span>/bin/zsh</span></span>
<span class="line"><span>如果你用的是 Zsh，那么你需要修改 ~/.zprofile 或 ~/.zshrc 文件。如果你用的是</span></span>
<span class="line"><span>Bash，那么你需要修改 ~/.bash_profile 或 ~/.bashrc 文件。你可以使用自带的 vi 编</span></span></code></pre></div><p>辑器进行编辑，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi ~/.zshrc</span></span>
<span class="line"><span># 或 vi ~/.bashrc</span></span>
<span class="line"><span>接着，按 i 键进入插入模式，再使用箭头键将光标移动到插入文本的位置，然后将下列内容</span></span></code></pre></div><p>复制粘贴到文本中。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANDROID_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME/Library/Android/sdk</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:$ANDROID_HOME/emulator</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:$ANDROID_HOME/platform-tools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">完成插入后，按</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Esc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 键退出插入模式，输入</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :wq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 以保存更改并退出</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 编辑器。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">再接着，为了让更改生效，你可以重启终端（Shell）或者运行</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 使配置生</span></span></code></pre></div><p>效。</p><p>最后，运行如下命令检查 Android 环境变量是否设置成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo $ANDROID_HOME</span></span>
<span class="line"><span>/Users/jianghongwei/Library/Android/sdk</span></span>
<span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/Users/local/bin...</span></span></code></pre></div><p>这一步依然可以参考视频。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/10.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/10.jpeg" alt=""></a></p><h2 id="安装-android-模拟器" tabindex="-1">安装 Android 模拟器 <a class="header-anchor" href="#安装-android-模拟器" aria-label="Permalink to &quot;安装 Android 模拟器&quot;">​</a></h2><p>第八步是安装 Android 模拟器。安装 Android 模拟器是搭建 Android 环境中的最后一步。当然你可以使用真机进行调试，但是模拟器大多数情况下更加方便，因此我选择安装了 Android 模拟器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果你还在 Welcome to Android Studio 页面，那么你可以在 More Actions 下拉框</span></span>
<span class="line"><span>中选择 Virtual Device Manager。其他情况，你可以在顶部菜单栏中点击 Tools &gt;</span></span>
<span class="line"><span>Virtual Device Manager。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/11.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 Device Manager 界面中，点击 Create Virtual Device 按钮创建虚拟设备。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/12.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 Virtual Device Configuration 页面选择虚拟硬件，你可以选择任意一个设备，比</span></span></code></pre></div><p>如 Pixel XL，然后点击 Next。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/13.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接着，你会进入到 Virtual Device Configuration 页面的 System Image 系统镜像</span></span></code></pre></div><p>选择步骤，选择模拟器的 Android 版本，然后点击下载按钮进行下载。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/14.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现在，你已成功创建了一个新的 Android 模拟器。回到 Device Manager 页面后，你将看到</span></span>
<span class="line"><span>新创建的模拟器设备。点击 Actions 中的播放图标 ▶️ 启动模拟器。接着会自动打开一个模</span></span></code></pre></div><p>拟器，并加载所选的 Android 系统镜像。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/15.png" alt=""></a></p><p>当你看到 Android 操作系统界面时，你的模拟器就安装完成了。此时，Android 环境已经搭建完成。接下来，我们将创建和启动 React Native 项目。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/16.png" alt=""></a></p><p>参考视频如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/17.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/17.jpeg" alt=""></a></p><h2 id="创建-react-native-项目" tabindex="-1">创建 React Native 项目 <a class="header-anchor" href="#创建-react-native-项目" aria-label="Permalink to &quot;创建 React Native 项目&quot;">​</a></h2><p>第九步是创建 React Native 项目。</p><p>你可以使用 React Native CLI 来创建一个新的 React Native 项目，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ npx react-native@latest init AwesomeProject</span></span></code></pre></div><p>运行上述命令后，会依次下载 JavaScript/Java/Objective-C 的相关依赖和项目模板，如果没有配置 NPM、Maven 或 CocoaPods 的相关镜像，很有可能会遇到运行失败的问题。在运行失败后，你需要确定一下是上述 3 个部分依赖中的哪部分依赖没有下载成功。</p><p>React Native iOS 环境中的 CocoaPods 报错，我已经在 iOS 环境搭建中解答过了，NPM镜像在前面步骤中也已经切换到淘宝源，这部分重点介绍 Android Maven 镜像源的替换。</p><p>例如，你可能会遇到如下图所示的 iOS Environment 安装失败的报错，但由于你要安装的是React Native Android，因此你可以选择忽略 iOS 的报错。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/18.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>再仔细观察图中内容，你可以看到 Donwloading template 、Copying template 、</span></span>
<span class="line"><span>Processing template 三个模板相关的步骤已经处理完成，报错的是 Installing</span></span>
<span class="line"><span>Bundler 这一步。</span></span></code></pre></div><p>这意味着，创建 React Native 项目已经完成，只是安装 Android 依赖失败了，所以你只需要切换 Maven 镜像源，再安装和启动 React Native 项目即可。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你需要打开 ./android/build.gradle 文件，将 Maven 源切换为阿里或华为的镜像源，</span></span></code></pre></div><p>操作方法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阿里：https://maven.aliyun.com/repository/public/</span></span>
<span class="line"><span>华为：https://repo.huaweicloud.com/repository/maven/</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/19.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>切换好源之后，你需要 cd android 目录，然后运行 gradlew build 命令，Android 依赖</span></span>
<span class="line"><span>安装是使用 gradlew 进行管理的。</span></span>
<span class="line"><span>$ cd android</span></span>
<span class="line"><span>$ ./gradlew build --refresh-dependencies</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/20.png" alt=""></a></p><p>参考视频如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/21.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/21.jpeg" alt=""></a></p><h2 id="启动-react-native-项目" tabindex="-1">启动 React Native 项目 <a class="header-anchor" href="#启动-react-native-项目" aria-label="Permalink to &quot;启动 React Native 项目&quot;">​</a></h2><p>最后一步就是启动 React Native 项目。</p><p>在上一步，我们已经完成了 React Native 项目的创建和 Maven 源的切换，所有准备工作都已经完成。这一步，我们需要完成：</p><ol><li><p>在本地启动 React Native 构建服务；</p></li><li><p>在模拟器中安装 React Native Android App。</p></li></ol><p>在项目的根目录中，运行如下命令，它会帮你在本地启动一个 React Native 构建服务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 如果在 Android 目录，需要 cd ../ 到根目录</span></span>
<span class="line"><span>$ npx react-native start</span></span>
<span class="line"><span>运行完成后，会出现如下的 Welcome to Metro 的欢迎界面，Metro 就是 React Native 的</span></span>
<span class="line"><span>构建服务。同时，底部会显示 r d i a 四个选项，其中 a 选项是 run on Android，也就</span></span>
<span class="line"><span>是说当你按下 a 按钮，它会帮你在模拟器上安装 React Native Android 应用。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/22.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按下 a 按钮后，稍等一会，当你看到 Welcome to React Native 页面时，你的 React Native</span></span></code></pre></div><p>Android 应用就安装完成了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/23.png" alt=""></a></p><p>参考视频如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/24.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3Android%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/24.jpeg" alt=""></a></p><p>至此，恭喜你，React Native Android 环境已经搭建成功了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>搭建开发环境是很多新手的痛点。React Native 项目依赖项繁多，首先是依赖 Android 环境，其次是依赖 Node.js 环境。Android 环境又依赖 Java 环境，还需要安装 Android Studio、Android SDK 和虚拟机。同时，Node.js 和 Java 的环境搭建也都依赖 Homebrew，环环相扣。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你在搭建 React Native 环境过程中，遇到过哪些问题？能把你的解决方案和大家分享分享吗？</p><p>期待你的输出，如果觉得有所收获，也欢迎你把今天的内容分享给更多的朋友！</p>`,130)])])}const h=a(n,[["render",E]]);export{c as __pageData,h as default};
